#!/usr/bin/env python3
"""
integrity_check.py - Perform checksum validation of loaded modules
"""

import hashlib
import importlib.util
import sys
from typing import Dict, List, Tuple


def calculate_file_hash(file_path: str, algorithm: str = 'sha256') -> str:
    """Calculate the hash of a file using the specified algorithm."""
    hash_func = hashlib.new(algorithm)

    try:
        with open(file_path, 'rb') as f:
            # Read file in chunks to handle large files efficiently
            for chunk in iter(lambda: f.read(4096), b""):
                hash_func.update(chunk)
        return hash_func.hexdigest()
    except (IOError, OSError) as e:
        print(f"Error reading file {file_path}: {e}")
        return None


def get_module_file_path(module_name: str) -> str:
    """Get the file path of a loaded module."""
    try:
        spec = importlib.util.find_spec(module_name)
        if spec and spec.origin:
            return spec.origin
        return None
    except (ImportError, AttributeError, ValueError):
        return None

def get_loaded_modules() -> List[str]:
    """Get a list of currently loaded module names."""
    return list(sys.modules.keys())

def validate_module_integrity(module_name: str, expected_hash: str = None, 
                             algorithm: str = 'sha256') -> Tuple[bool, str, str]:
    """
    Validate the integrity of a module by comparing its hash with expected value.

    Args:
        module_name: Name of the module to validate
        expected_hash: Expected hash value (if None, just returns the calculated hash)
        algorithm: Hash algorithm to use (default: sha256)

    Returns:
        Tuple of (is_valid, calculated_hash, file_path)
    """
    file_path = get_module_file_path(module_name)

    if not file_path:
        return False, None, None

    calculated_hash = calculate_file_hash(file_path, algorithm)

    if calculated_hash is None:
        return False, None, file_path

    # If no expected hash provided, just return the calculated one
    if expected_hash is None:
        return True, calculated_hash, file_path

    is_valid = calculated_hash.lower() == expected_hash.lower()
    return is_valid, calculated_hash, file_path

def main():
    """Main function to run the integrity check."""
    print("Starting module integrity check...")
    print(f"Using hash algorithm: sha256\n")

    # Get all loaded modules
    modules = get_loaded_modules()
    total_modules = len(modules)

    print(f"Checking integrity of {total_modules} loaded modules...")

    # Dictionary to store results
    results = {}
    valid_count = 0
    invalid_count = 0
    error_count = 0

    # Check each module
    for i, module_name in enumerate(sorted(modules), 1):
        # Skip built-in modules (they don't have file paths)
        file_path = get_module_file_path(module_name)
        if not file_path:
            continue

        is_valid, calculated_hash, _ = validate_module_integrity(module_name, algorithm='sha256')

        if is_valid:
            valid_count += 1
            results[module_name] = {'status': 'VALID', 'hash': calculated_hash}
        elif calculated_hash:
            invalid_count += 1
            results[module_name] = {'status': 'INVALID', 'hash': calculated_hash}
        else:
            error_count += 1
            results[module_name] = {'status': 'ERROR', 'hash': None}

        # Print progress every 100 modules
        if i % 100 == 0:
            print(f"Progress: {i}/{total_modules} modules checked")

    # Print summary
    print("\n--- INTEGRITY CHECK COMPLETE ---")
    print(f"Total modules checked: {valid_count + invalid_count}")
    print(f"Valid modules: {valid_count}")
    print(f"Invalid modules: {invalid_count}")
    print(f"Modules with errors: {error_count}")

    # Print invalid modules
    if invalid_count > 0:
        print("\nINVALID MODULES:")
        for module_name, data in results.items():
            if data['status'] == 'INVALID':
                print(f"  {module_name}")

    # Print modules with errors
    if error_count > 0:
        print("\nMODULES WITH ERRORS:")
        for module_name, data in results.items():
            if data['status'] == 'ERROR':
                print(f"  {module_name}")

    # Exit with error code if any invalid modules found
    if invalid_count > 0:
        sys.exit(1)

    print("\nAll module integrity checks passed.")
    sys.exit(0)

if __name__ == "__main__":
    main()
